//! The Lucide glyphs of DESIGN.md 4, flattened to polylines.
//!
//! `tools/icons.py` writes this file from `crates/app/assets/icons`.
//! Do not edit it by hand. Every point sits in the 24 x 24 grid of the
//! Lucide set. The set is under the ISC license; see the LICENSE file
//! beside the SVG files.

// Rust guideline compliant 2026-02-21

/// One closed or open run of points in the 24 x 24 grid.
pub struct Stroke {
    /// The points of the run, in order.
    pub points: &'static [(f32, f32)],
    /// Whether the last point joins the first one.
    pub closed: bool,
}

impl std::fmt::Debug for Stroke {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("Stroke").finish_non_exhaustive()
    }
}

/// Every glyph the UI draws.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Icon {
    /// The Lucide `check` glyph.
    Check,
    /// The Lucide `chevron-down` glyph.
    ChevronDown,
    /// The Lucide `chevron-right` glyph.
    ChevronRight,
    /// The Lucide `eye-off` glyph.
    EyeOff,
    /// The Lucide `eye` glyph.
    Eye,
    /// The Lucide `flip-horizontal-2` glyph.
    FlipHorizontal2,
    /// The Lucide `folder` glyph.
    Folder,
    /// The Lucide `grid-3x3` glyph.
    Grid3x3,
    /// The Lucide `image` glyph.
    Image,
    /// The Lucide `info` glyph.
    Info,
    /// The Lucide `keyboard` glyph.
    Keyboard,
    /// The Lucide `layers` glyph.
    Layers,
    /// The Lucide `monitor-off` glyph.
    MonitorOff,
    /// The Lucide `monitor` glyph.
    Monitor,
    /// The Lucide `mouse-pointer` glyph.
    MousePointer,
    /// The Lucide `plus` glyph.
    Plus,
    /// The Lucide `rotate-cw` glyph.
    RotateCw,
    /// The Lucide `ruler` glyph.
    Ruler,
    /// The Lucide `sliders-horizontal` glyph.
    SlidersHorizontal,
    /// The Lucide `sun` glyph.
    Sun,
    /// The Lucide `trash` glyph.
    Trash,
    /// The Lucide `x` glyph.
    X,
}

impl Icon {
    /// The runs that draw the glyph.
    pub fn strokes(self) -> &'static [Stroke] {
        match self {
            Self::Check => &CHECK,
            Self::ChevronDown => &CHEVRON_DOWN,
            Self::ChevronRight => &CHEVRON_RIGHT,
            Self::EyeOff => &EYE_OFF,
            Self::Eye => &EYE,
            Self::FlipHorizontal2 => &FLIP_HORIZONTAL_2,
            Self::Folder => &FOLDER,
            Self::Grid3x3 => &GRID_3X3,
            Self::Image => &IMAGE,
            Self::Info => &INFO,
            Self::Keyboard => &KEYBOARD,
            Self::Layers => &LAYERS,
            Self::MonitorOff => &MONITOR_OFF,
            Self::Monitor => &MONITOR,
            Self::MousePointer => &MOUSE_POINTER,
            Self::Plus => &PLUS,
            Self::RotateCw => &ROTATE_CW,
            Self::Ruler => &RULER,
            Self::SlidersHorizontal => &SLIDERS_HORIZONTAL,
            Self::Sun => &SUN,
            Self::Trash => &TRASH,
            Self::X => &X,
        }
    }
}

